{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investments — Programs & Packages</title>
  <style>
    :root{--bg:#fbfaf8;--card:#ffffff;--muted:#6b6b6b;--accent:#6a8f6a;--accent-2:#b07c6c;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial;color:#222}
    body{background-image:url('assets/img/pattern.svg');background-repeat:repeat; background-size:200px; background-color:var(--bg);}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.7),transparent);backdrop-filter:blur(6px)}
    nav a{margin:0 12px;color:#333;text-decoration:none;font-weight:600;font-size:14px}
    .brand{font-weight:700;letter-spacing:0.6px}
    .wrap{max-width:1100px;margin:32px auto;padding:20px}
    .hero{display:flex;gap:28px;align-items:center}
    .hero .intro{flex:1}
    h1{margin:0 0 8px 0;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .toggle{display:flex;align-items:center;margin-top:18px}
    .switch{width:56px;height:32px;background:#e9e9e9;border-radius:999px;position:relative;cursor:pointer;margin-right:12px}
    .knob{width:26px;height:26px;border-radius:50%;background:white;position:absolute;top:3px;left:3px;box-shadow:0 3px 8px rgba(0,0,0,0.12);transition:left .28s cubic-bezier(.2,.9,.3,1)}
    .switch.on{background:linear-gradient(90deg,var(--accent),var(--accent-2))}
    .switch.on .knob{left:27px}
    .label{font-size:13px;color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:24px}
    .card{background:var(--card);border-radius:10px;padding:18px;box-shadow:0 6px 18px rgba(20,20,20,0.04);display:flex;flex-direction:column}
    .card h3{margin:0 0 6px 0;font-size:16px}
    .price{font-size:22px;font-weight:700;margin:8px 0;color:#222}
    .meta{font-size:13px;color:var(--muted)}
    .cta{margin-top:auto;padding:10px 12px;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;border:none;border-radius:8px;cursor:pointer;font-weight:700}
    .small{font-size:12px;color:var(--muted);margin-top:10px}
    footer{padding:26px;text-align:center;color:var(--muted);font-size:13px}
    .note{background:#fff7ee;border-left:4px solid var(--accent-2);padding:10px;border-radius:6px;margin-top:12px;font-size:13px}
    @media(max-width:880px){.grid{grid-template-columns:1fr}.hero{flex-direction:column}.wrap{padding:12px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">Welcome</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Practices</a>
      <a href="blends.html">Bespoke Blends</a>
      <a href="shop.html">Marketplace</a>
      <a href="pricing.html">Investments</a>
      <a href="about.html">Team</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero">
      <div class="intro">
        <h1>Programs and one-off engagements</h1>
        <p class="lead">Simplified offerings framed as choices: ongoing support, compact session packages, or a focused VIP Day. Pricing below switches between monthly plans and single-package investments.</p>

        <div class="toggle" aria-hidden="false">
          <div id="pricingSwitch" class="switch" tabindex="0" role="button" aria-pressed="false">
            <div class="knob"></div>
          </div>
          <div class="label">View: <strong id="viewMode">Monthly</strong></div>
        </div>

        <div class="note">All sessions are safety-forward: formulations follow dilution guidance and include patch-test recommendations. See FAQ for notes on pregnancy and pets.</div>
      </div>
      <div style="width:320px">
        <div style="background:linear-gradient(180deg,rgba(255,255,255,0.5),transparent);border-radius:10px;padding:14px;box-shadow:0 8px 20px rgba(30,30,30,0.04)">
          <strong>Compare at a glance</strong>
          <p class="meta" style="margin-top:8px">Toggle to animate the price perspective. Numbers represent suggested investment and do not include taxes or add-ons.</p>
        </div>
      </div>
    </section>

    <section class="grid" aria-live="polite">
      <article class="card">
        <h3>Starter Rituals</h3>
        <div class="price"><span class="amount" data-monthly="28" data-package="78">$28</span><span class="unit">/mo</span></div>
        <div class="meta">Monthly access to two short guided scent sessions; package equals three single visits.</div>
        <div class="small">Includes basic blend formula and usage notes.</div>
        <button class="cta" data-href="{{PRIMARY_CTA_URL}}?pkg=starter">{{PRIMARY_CTA_LABEL}}</button>
      </article>

      <article class="card">
        <h3>Balance Sequence</h3>
        <div class="price"><span class="amount" data-monthly="68" data-package="195">$68</span><span class="unit">/mo</span></div>
        <div class="meta">A 3-session pack or a subscription for steady practice: guided sessions plus a custom portable blend.</div>
        <div class="small">Recommended for those building a short daily ritual.</div>
        <button class="cta" data-href="{{PRIMARY_CTA_URL}}?pkg=balance">{{PRIMARY_CTA_LABEL}}</button>
      </article>

      <article class="card">
        <h3>Signature Immersion — VIP Day</h3>
        <div class="price"><span class="amount" data-monthly="190" data-package="750">$190</span><span class="unit">/mo</span></div>
        <div class="meta">A focused full-day immersion (single package) for comprehensive scent strategy; available as a one-off investment.</div>
        <div class="small">Includes extended consultation, custom formulas, and an at-home plan.</div>
        <button class="cta" data-href="{{PRIMARY_CTA_URL}}?pkg=vip">{{PRIMARY_CTA_LABEL}}</button>
      </article>
    </section>

  </main>

  <footer>
    <div>Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </footer>

  <script>
    // Pricing toggle with animated numbers
    (function(){
      const switchEl = document.getElementById('pricingSwitch');
      const viewText = document.getElementById('viewMode');
      const amounts = Array.from(document.querySelectorAll('.amount'));
      let mode = 'monthly';

      function animate(el, from, to){
        const duration = 550;
        let start = null;
        function step(ts){
          if (!start) start = ts;
          const progress = Math.min((ts - start)/duration,1);
          const value = Math.round(from + (to - from)*progress);
          el.textContent = '$' + value;
          if(progress < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      function updateMode(newMode){
        mode = newMode;
        viewText.textContent = (mode === 'monthly') ? 'Monthly' : 'Package';
        document.querySelectorAll('.unit').forEach(u=>u.textContent = (mode === 'monthly') ? '/mo' : '');
        amounts.forEach(a=>{
          const from = parseInt(a.textContent.replace(/[^0-9]/g,''),10) || 0;
          const to = parseInt(a.dataset[newMode],10) || 0;
          animate(a, from, to);
        });
        if(mode === 'package') switchEl.classList.add('on'); else switchEl.classList.remove('on');
        switchEl.setAttribute('aria-pressed', mode === 'package');
      }

      switchEl.addEventListener('click', ()=>{
        updateMode(mode === 'monthly' ? 'package' : 'monthly');
      });

      // Initialize
      amounts.forEach(a=>a.textContent = '$' + a.dataset['monthly']);
      updateMode('monthly');

      // Wire CTAs
      document.querySelectorAll('.cta').forEach(b=>{
        b.addEventListener('click', ()=>{
          const href = b.dataset.href || '{{PRIMARY_CTA_URL}}';
          location.href = href;
        });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Team & Approach</title>
  <style>
    :root{--bg:#fffdfb;--muted:#666;--accent:#7d9a75}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;color:#111;background:var(--bg);}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px;background:#fff;border-bottom:1px solid #eee}
    nav a{margin:0 10px;text-decoration:none;color:#333;font-weight:600}
    .wrap{max-width:980px;margin:28px auto;padding:18px}
    .hero{display:grid;grid-template-columns:2fr 1fr;gap:18px;align-items:start}
    h1{margin:0 0 8px 0;font-size:26px}
    p.lead{margin:0;color:var(--muted)}
    .bio{background:#fff;padding:16px;border-radius:10px;box-shadow:0 8px 20px rgba(10,10,10,0.04)}
    .selector{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}
    .mood{padding:8px 12px;border-radius:999px;background:#f6f6f6;border:1px solid #eee;cursor:pointer;font-weight:600}
    .mood.active{background:linear-gradient(90deg,var(--accent),#b07c6c);color:white}
    .method{margin-top:14px;padding:12px;background:linear-gradient(180deg,rgba(255,255,255,0.9),#fff);border-radius:8px}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:white;border-radius:8px;text-decoration:none;font-weight:700}
    details.faq{margin-top:14px}
    .note{font-size:13px;color:var(--muted);margin-top:8px}
    @media(max-width:820px){.hero{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">Welcome</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Practices</a>
      <a href="blends.html">Bespoke Blends</a>
      <a href="shop.html">Marketplace</a>
      <a href="pricing.html">Investments</a>
      <a href="about.html">Team</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero">
      <div>
        <h1>Philosophy & practitioner notes</h1>
        <p class="lead">A practice rooted in scent literacy and pragmatic routines. We craft methods that may support short- and longer-term rhythms: inhalation tools, topical roll-ons, and at-home mists.</p>

        <div class="bio">
          <strong>Lead practitioner</strong>
          <p class="note">A licensed aromatherapist with a background in botanical formulation and safety protocols. Consultations include dilution guidance and a recommended patch test.</p>

          <div style="margin-top:10px">
            <strong>Choose how you feel</strong>
            <div class="selector" role="list">
              <div class="mood" data-method="inhalation">Tense</div>
              <div class="mood" data-method="roll-on">Foggy</div>
              <div class="mood" data-method="mist">Overwhelmed</div>
              <div class="mood" data-method="blend-kit">Low Energy</div>
            </div>

            <div id="recommend" class="method" aria-live="polite">
              <strong>Recommended approach</strong>
              <p id="recText">Select a state to see a suggested method and the best next step.</p>
              <a id="recCta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            </div>
          </div>
        </div>

        <details class="faq">
          <summary style="font-weight:700">Safety & common questions</summary>
          <div style="margin-top:8px">
            <p class="note">Dilution: topical products are formulated to safe dilution ranges; you will receive clear instructions. Always perform a patch test on a small area and wait 24 hours before broader use.</p>
            <p class="note">Pets: certain essential oils can affect animals. We provide pet-safe alternatives and guidance when needed.</p>
            <p class="note">Pregnancy: some oils are not recommended during pregnancy. Notify your practitioner and we will design pregnancy-appropriate options.</p>
          </div>
        </details>
      </div>

      <aside>
        <div style="background:#fff;padding:16px;border-radius:10px;box-shadow:0 10px 24px rgba(10,10,10,0.05)">
          <strong>How we name methods</strong>
          <p class="note">Methods are framed by delivery (inhalation, topical, ambient) and intention. No promises — phrasing centers on what the approach may support.</p>
          <div style="margin-top:12px">
            <strong>Contact</strong>
            <p class="note">Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">Email</a> for practitioner availability.</p>
          </div>
        </div>
      </aside>
    </section>
  </main>

  <script>
    // Mood-to-Method selector
    (function(){
      const moods = document.querySelectorAll('.mood');
      const recText = document.getElementById('recText');
      const recCta = document.getElementById('recCta');

      const map = {
        'inhalation':{title:'Short inhalation sequence',desc:'A focused inhalation practice with a small personal inhaler; quick to use and portable.',cta:'Reserve an Inhalation Session'},
        'roll-on':{title:'Topical roll-on ritual',desc:'A pre-diluted roll-on for targeted application and practical reapplication throughout the day.',cta:'Request a Roll-On Formula'},
        'mist':{title:'Ambient mist + micro-practice',desc:'A room mist paired with a 3-minute guided routine for a calmer environment.',cta:'Order a Mist Session'},
        'blend-kit':{title:'Mini blend kit',desc:'A curated kit to support low-energy moments: easy instructions and refill guidance.',cta:'Get a Mini Kit'}
      };

      moods.forEach(m=>{
        m.addEventListener('click', ()=>{
          moods.forEach(x=>x.classList.remove('active'));
          m.classList.add('active');
          const method = m.dataset.method;
          const data = map[method];
          // animate text swap
          recText.style.opacity = 0; recCta.style.opacity = 0;
          setTimeout(()=>{
            recText.innerHTML = '<strong>'+data.title+'</strong><br>'+data.desc;
            recCta.textContent = data.cta;
            // attach method hint to CTA
            const base = '{{PRIMARY_CTA_URL}}';
            recCta.href = base + '?method=' + encodeURIComponent(method);
            recText.style.opacity = 1; recCta.style.opacity = 1;
          },220);
        });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve a Session</title>
  <style>
    :root{--bg:#fffefc;--muted:#6b6b6b;--accent:#7aa07a}
    body{margin:0;font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial;color:#111;background:var(--bg)}
    header{padding:14px 20px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #eee}
    nav a{margin:0 10px;text-decoration:none;color:#333;font-weight:600}
    .wrap{max-width:980px;margin:26px auto;padding:18px}
    h1{margin:0 0 10px 0}
    .grid{display:grid;grid-template-columns:1fr 380px;gap:18px}
    form{background:#fff;padding:14px;border-radius:10px;box-shadow:0 10px 28px rgba(10,10,10,0.04)}
    label{display:block;font-weight:700;margin-top:10px;font-size:13px}
    input,select,textarea{width:100%;padding:10px;margin-top:6px;border-radius:8px;border:1px solid #e6e6e6}
    .moods{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
    .moodBtn{padding:8px 12px;border-radius:999px;border:1px solid #eee;background:#fafafa;cursor:pointer}
    .moodBtn.active{background:linear-gradient(90deg,var(--accent),#b07c6c);color:#fff}
    .summary{background:#fff;padding:14px;border-radius:10px;box-shadow:0 8px 20px rgba(10,10,10,0.04)}
    .bookNow{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none;font-weight:700}
    .muted{color:var(--muted);font-size:13px}
    @media(max-width:820px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">Welcome</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Practices</a>
      <a href="blends.html">Bespoke Blends</a>
      <a href="shop.html">Marketplace</a>
      <a href="pricing.html">Investments</a>
      <a href="about.html">Team</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Reserve a session or the VIP Day</h1>
    <p class="muted">Choose what you need, select a mood to see the suggested method, then finalize your request.</p>

    <div class="grid">
      <form id="bookForm">
        <label for="name">Full name</label>
        <input id="name" name="name" required>

        <label for="email">Email</label>
        <input id="email" name="email" type="email" required>

        <label>Pick a mood</label>
        <div class="moods" role="list">
          <button type="button" class="moodBtn" data-method="inhalation">Tense</button>
          <button type="button" class="moodBtn" data-method="roll-on">Foggy</button>
          <button type="button" class="moodBtn" data-method="mist">Overwhelmed</button>
          <button type="button" class="moodBtn" data-method="kit">Low Energy</button>
        </div>

        <label for="option">Choose an offering</label>
        <select id="option" name="option">
          <option value="starter">Starter Ritual — single</option>
          <option value="sequence">Balance Sequence — 3-pack</option>
          <option value="vip">Signature Immersion — VIP Day</option>
        </select>

        <label for="note">Notes (allergies, pregnancy, pets)</label>
        <textarea id="note" name="note" rows="3" placeholder="Share anything relevant; will inform safe choices."></textarea>

        <div style="margin-top:12px">
          <button class="bookNow" id="finalCta" type="submit">{{PRIMARY_CTA_LABEL}}</button>
          <div style="margin-top:8px" class="muted">We recommend a patch test for topical products. If pregnant or caring for small animals, mention it above.</div>
        </div>
      </form>

      <aside class="summary" aria-live="polite">
        <strong>Session preview</strong>
        <div id="preview" style="margin-top:8px">Select a mood and offering to see a short summary.</div>
        <div style="margin-top:12px" class="muted">After requesting, you will receive a confirmation and a pre-session safety brief.</div>
      </aside>
    </div>
  </main>

  <script>
    // Mood-to-Method + form behavior
    (function(){
      const moodBtns = document.querySelectorAll('.moodBtn');
      const preview = document.getElementById('preview');
      const finalCta = document.getElementById('finalCta');
      const form = document.getElementById('bookForm');
      let chosenMethod = null;

      const map = {
        'inhalation':{label:'Inhalation sequence',desc:'Personal inhaler and 10-minute guided session.'},
        'roll-on':{label:'Topical roll-on',desc:'Pre-diluted roll-on plus application coaching.'},
        'mist':{label:'Ambient mist routine',desc:'Room mist with a short ambient practice.'},
        'kit':{label:'Mini blend kit',desc:'A small at-home kit with simple instructions.'}
      };

      moodBtns.forEach(b=>{
        b.addEventListener('click', ()=>{
          moodBtns.forEach(x=>x.classList.remove('active'));
          b.classList.add('active');
          chosenMethod = b.dataset.method;
          updatePreview();
        });
      });

      function updatePreview(){
        const offering = document.getElementById('option').value;
        const methodInfo = map[chosenMethod] || {label:'No selection',desc:'Choose a mood.'};
        const lines = [];
        lines.push('<strong>'+methodInfo.label+'</strong>');
        lines.push(methodInfo.desc);
        lines.push('<em>Offering:</em> ' + offering.replace('-', ' '));
        preview.innerHTML = lines.join('<br>');
        // Update CTA to reflect method
        const text = chosenMethod ? ('Request: ' + methodInfo.label) : '{{PRIMARY_CTA_LABEL}}';
        finalCta.textContent = text;
        // keep link destination placeholder but add hint via data
        finalCta.dataset.href = '{{PRIMARY_CTA_URL}}?method=' + (chosenMethod || 'none') + '&offer=' + offering;
      }

      document.getElementById('option').addEventListener('change', updatePreview);

      form.addEventListener('submit', function(e){
        e.preventDefault();
        // simple client-side 'booking' flow: open mailto with summary
        const name = document.getElementById('name').value;
        const email = document.getElementById('email').value;
        const note = document.getElementById('note').value;
        const offering = document.getElementById('option').value;
        const methodInfo = map[chosenMethod] ? chosenMethod : 'unspecified';
        const subject = encodeURIComponent('Booking request from ' + name);
        const body = encodeURIComponent('Name: '+name+'\nEmail: '+email+'\nMethod: '+methodInfo+'\nOffering: '+offering+'\nNotes: '+note);
        // fallback to primary CTA URL when available
        const href = finalCta.dataset.href || '{{PRIMARY_CTA_URL}}';
        // attempt to open mail client then go to CTA URL
        location.href = 'mailto:{{EMAIL}}?subject='+subject+'&body='+body;
        setTimeout(()=>{ location.href = href; }, 600);
      });

      // init
      updatePreview();
    })();
  </script>
</body>
</html>"} 
